/**
 * @fileoverview MongoDB database connection utility.
 * Provides a singleton connection pattern optimized for Next.js serverless environment.
 * Reuses connections in development to prevent connection pool exhaustion during hot reloading.
 * @module lib/mongodb
 */
import { MongoClient } from 'mongodb'

/**
 * Global declaration for MongoDB client promise.
 * Allows connection reuse across hot reloads in development.
 */
declare global {
  // eslint-disable-next-line no-var
  var _mongoClientPromise: Promise<MongoClient> | undefined
}

if (!process.env.MONGODB_URI) {
  throw new Error('Missing MONGODB_URI env var')
}
const uri = process.env.MONGODB_URI

const options = {}

let client: MongoClient
let clientPromise: Promise<MongoClient>

/**
 * Connection initialization with environment-aware caching.
 * In development: Reuses global promise to prevent connection exhaustion.
 * In production: Creates fresh connection per instance.
 */
if (process.env.NODE_ENV === 'development') {
  if (!global._mongoClientPromise) {
    client = new MongoClient(uri!, options)
    global._mongoClientPromise = client.connect()
